896	        if ((sInfo.flags & ServiceInfo.FLAG_ISOLATED_PROCESS) == 0
897	                || (inPrivateSharedIsolatedProcess && !isDefaultProcessService(sInfo))) {
898	            // For regular processes, or private package-shared isolated processes, just the name
899	            // in sInfo
