945	    ComponentName startServiceLocked(IApplicationThread caller, Intent service, String resolvedType,
946	            int callingPid, int callingUid, boolean fgRequired,
947	            String callingPackage, @Nullable String callingFeatureId, final int userId,
948	            BackgroundStartPrivileges backgroundStartPrivileges, boolean isSdkSandboxService,
949	            int sdkSandboxClientAppUid, String sdkSandboxClientAppPackage, String instanceName)
950	            throws TransactionTooLargeException {
951	        if (DEBUG_DELAYED_STARTS) Slog.v(TAG_SERVICE, "startService: " + service
952	                + " type=" + resolvedType + " args=" + service.getExtras());
953	
954	        final boolean callerFg;
955	        if (caller != null) {
956	            final ProcessRecord callerApp = mAm.getRecordForAppLOSP(caller);
957	            if (callerApp == null) {
958	                throw new SecurityException(
959	                        "Unable to find app for caller " + caller
960	                        + " (pid=" + callingPid
961	                        + ") when starting service " + service);
962	            }
963	            callerFg = callerApp.mState.getSetSchedGroup() != ProcessList.SCHED_GROUP_BACKGROUND;
964	        } else {
965	            callerFg = true;
966	        }
967	
968	        ServiceLookupResult res = retrieveServiceLocked(service, instanceName, isSdkSandboxService,
969	                sdkSandboxClientAppUid, sdkSandboxClientAppPackage, resolvedType, callingPackage,
970	                callingPid, callingUid, userId, true, callerFg, false, false, null, false, false);
971	        if (res == null) {
972	            return null;
973	        }
974	        if (res.record == null) {
975	            return new ComponentName("!", res.permission != null
976	                    ? res.permission : "private to package");
977	        }
978	
979	        ServiceRecord r = res.record;
980	
981	        traceInstant("startService(): ", r);
982	
983	        // Note, when startService() or startForegroundService() is called on an already
984	        // running SHORT_SERVICE FGS, the call will succeed (i.e. we won't throw
985	        // ForegroundServiceStartNotAllowedException), even when the service is already timed
986	        // out. This is because these APIs will essentially only change the "started" state
987	        // of the service, and it won't affect "the foreground-ness" of the service, or the type
988	        // of the FGS.
989	        // However, this call will still _not_ extend the SHORT_SERVICE timeout either.
990	        // Also, if the app tries to change the type of the FGS later (using
991	        // Service.startForeground()), at that point we will consult the BFSL check and the timeout
992	        // and make the necessary decisions.
993	        setFgsRestrictionLocked(callingPackage, callingPid, callingUid, service, r, userId,
994	                backgroundStartPrivileges, false /* isBindService */);
995	
996	        if (!mAm.mUserController.exists(r.userId)) {
997	            Slog.w(TAG, "Trying to start service with non-existent user! " + r.userId);
998	            return null;
999	        }

