1650	    int stopServiceLocked(IApplicationThread caller, Intent service,
1651	            String resolvedType, int userId, boolean isSdkSandboxService,
1652	            int sdkSandboxClientAppUid, String sdkSandboxClientAppPackage, String instanceName) {
1653	        if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "stopService: " + service
1654	                + " type=" + resolvedType);
1655	
1656	        final ProcessRecord callerApp = mAm.getRecordForAppLOSP(caller);
1657	        if (caller != null && callerApp == null) {
1658	            throw new SecurityException(
1659	                    "Unable to find app for caller " + caller
1660	                    + " (pid=" + mAm.mInjector.getCallingPid()
1661	                    + ") when stopping service " + service);
1662	        }
1663	
1664	        // If this service is active, make sure it is stopped.
1665	        ServiceLookupResult r = retrieveServiceLocked(service, instanceName, isSdkSandboxService,
1666	                sdkSandboxClientAppUid, sdkSandboxClientAppPackage, resolvedType, null,
1667	                mAm.mInjector.getCallingPid(), mAm.mInjector.getCallingUid(),
1668	                userId, false, false, false, false, null, false, false);
1669	        if (r != null) {
1670	            if (r.record != null) {
