1685	    void stopInBackgroundLocked(int uid) {
1686	        // Stop all services associated with this uid due to it going to the background
1687	        // stopped state.
1688	        ServiceMap services = mServiceMap.get(UserHandle.getUserId(uid));
1689	        ArrayList<ServiceRecord> stopping = null;
1690	        if (services != null) {
1691	            for (int i = services.mServicesByInstanceName.size() - 1; i >= 0; i--) {
1692	                ServiceRecord service = services.mServicesByInstanceName.valueAt(i);
1693	                if (service.appInfo.uid == uid && service.startRequested) {
1694	                    if (mAm.getAppStartModeLOSP(service.appInfo.uid, service.packageName,
1695	                            service.appInfo.targetSdkVersion, -1, false, false, false)
1696	                            != ActivityManager.APP_START_MODE_NORMAL) {
1697	                        if (stopping == null) {
1698	                            stopping = new ArrayList<>();
1699	                        }
1700	                        String compName = service.shortInstanceName;
1701	                        EventLogTags.writeAmStopIdleService(service.appInfo.uid, compName);
1702	                        StringBuilder sb = new StringBuilder(64);
1703	                        sb.append("Stopping service due to app idle: ");
1704	                        UserHandle.formatUid(sb, service.appInfo.uid);
1705	                        sb.append(" ");
1706	                        TimeUtils.formatDuration(service.createRealTime
1707	                                - SystemClock.elapsedRealtime(), sb);
1708	                        sb.append(" ");
1709	                        sb.append(compName);
1710	                        Slog.w(TAG, sb.toString());
1711	                        stopping.add(service);
1712	
1713	                        // If the app is under bg restrictions, also make sure that
1714	                        // any notification is dismissed
1715	                        if (appRestrictedAnyInBackground(
1716	                                service.appInfo.uid, service.packageName)) {
1717	                            cancelForegroundNotificationLocked(service);
1718	                        }
1719	                    }
1720	                }
1721	            }
1722	            if (stopping != null) {
1723	                final int size = stopping.size();
1724	                for (int i = size - 1; i >= 0; i--) {
1725	                    ServiceRecord service = stopping.get(i);
1726	                    service.delayed = false;
1727	                    services.ensureNotStartingBackgroundLocked(service);
1728	                    stopServiceLocked(service, true);
1729	                }
1730	                if (size > 0) {
1731	                    mAm.updateOomAdjPendingTargetsLocked(OOM_ADJ_REASON_UID_IDLE);
1732	                }
1733	            }
1734	        }
1735	    }
