1784	                + " " + token + " startId=" + startId);
1785	        ServiceRecord r = findServiceLocked(className, token, UserHandle.getCallingUserId());
1786	        if (r != null) {
1787	            if (startId >= 0) {
1788	                // Asked to only stop if done with all work.  Note that
1789	                // to avoid leaks, we will take this as dropping all
1790	                // start items up to and including this one.
1791	                ServiceRecord.StartItem si = r.findDeliveredStart(startId, false, false);
1792	                if (si != null) {
