1794	                        ServiceRecord.StartItem cur = r.deliveredStarts.remove(0);
1795	                        cur.removeUriPermissionsLocked();
1796	                        if (cur == si) {
1797	                            break;
1798	                        }
1799	                    }
1800	                }
1801	
1802	                if (r.getLastStartId() != startId) {
1803	                    return false;
1804	                }
1805	
1806	                if (r.deliveredStarts.size() > 0) {
1807	                    Slog.w(TAG, "stopServiceToken startId " + startId
1808	                            + " is last, but have " + r.deliveredStarts.size()
1809	                            + " remaining args");
1810	                }
1811	            }
1812	
1813	            maybeStopShortFgsTimeoutLocked(r);
1814	            maybeStopFgsTimeoutLocked(r);
1815	
1816	            final int uid = r.appInfo.uid;
1817	            final String packageName = r.name.getPackageName();
1818	            final String serviceName = r.name.getClassName();
1819	            FrameworkStatsLog.write(FrameworkStatsLog.SERVICE_STATE_CHANGED, uid, packageName,
1820	                    serviceName, FrameworkStatsLog.SERVICE_STATE_CHANGED__STATE__STOP);
1821	            mAm.mBatteryStatsService.noteServiceStopRunning(uid, packageName, serviceName);
1822	            mAm.mProcessStateController.setStartRequested(r, false);
1823	            if (r.tracker != null) {
1824	                synchronized (mAm.mProcessStats.mLock) {
1825	                    r.tracker.setStarted(false, mAm.mProcessStats.getMemFactorLocked(),
1826	                            SystemClock.uptimeMillis());
1827	                }
1828	            }
1829	            r.callStart = false;
