1929	    void updateForegroundApps(ServiceMap smap) {
1930	        // This is called from the handler without the lock held.
1931	        synchronized (mAm) {
1932	            final long now = SystemClock.elapsedRealtime();
1933	            long nextUpdateTime = Long.MAX_VALUE;
1934	            if (smap != null) {
1935	                if (DEBUG_FOREGROUND_SERVICE) Slog.d(TAG, "Updating foreground apps for user "
1936	                        + smap.mUserId);
1937	                smap.mPendingRemoveForegroundApps.clear();
1938	                for (int i = smap.mActiveForegroundApps.size()-1; i >= 0; i--) {
1939	                    ActiveForegroundApp aa = smap.mActiveForegroundApps.valueAt(i);
1940	                    if (aa.mEndTime != 0) {
1941	                        boolean canRemove = foregroundAppShownEnoughLocked(aa, now);
1942	                        if (canRemove) {
1943	                            // This was up for longer than the timeout, so just remove immediately.
1944	                            smap.mPendingRemoveForegroundApps.add(smap.mActiveForegroundApps.keyAt(i));
1945	                            smap.mActiveForegroundAppsChanged = true;
1946	                            continue;
1947	                        }
1948	                        if (aa.mHideTime < nextUpdateTime) {
1949	                            nextUpdateTime = aa.mHideTime;
1950	                        }
1951	                    }
1952	                    if (!aa.mAppOnTop) {
1953	                        // Transitioning a fg-service host app out of top: if it's bg restricted,
1954	                        // it loses the fg service state now.
1955	                        if (isForegroundServiceAllowedInBackgroundRestricted(
1956	                                aa.mUid, aa.mPackageName)) {
1957	                            if (DEBUG_FOREGROUND_SERVICE) Slog.d(TAG, "Adding active: pkg="
1958	                                    + aa.mPackageName + ", uid=" + aa.mUid);
1959	                        } else {
1960	                            if (DEBUG_FOREGROUND_SERVICE) {
1961	                                Slog.d(TAG, "bg-restricted app "
1962	                                        + aa.mPackageName + "/" + aa.mUid
1963	                                        + " exiting top; demoting fg services ");
1964	                            }
1965	                            stopAllForegroundServicesLocked(aa.mUid, aa.mPackageName);
1966	                        }
1967	                    }
1968	                }
1969	                for(int i = smap.mPendingRemoveForegroundApps.size() - 1; i >= 0; i--) {
1970	                    smap.mActiveForegroundApps.remove(smap.mPendingRemoveForegroundApps.get(i));
1971	                }
1972	                smap.removeMessages(ServiceMap.MSG_UPDATE_FOREGROUND_APPS);
1973	                if (nextUpdateTime < Long.MAX_VALUE) {
1974	                    if (DEBUG_FOREGROUND_SERVICE) Slog.d(TAG, "Next update time in: "
1975	                            + (nextUpdateTime-now));
1976	                    Message msg = smap.obtainMessage(ServiceMap.MSG_UPDATE_FOREGROUND_APPS);
1977	                    smap.sendMessageAtTime(msg, nextUpdateTime
1978	                            + SystemClock.uptimeMillis() - SystemClock.elapsedRealtime());
1979	                }
1980	            }
1981	            smap.mActiveForegroundAppsChanged = false;
1982	        }
1983	    }
