1996	    private void decActiveForegroundAppLocked(ServiceMap smap, ServiceRecord r) {
1997	        ActiveForegroundApp active = smap.mActiveForegroundApps.get(r.packageName);
1998	        if (active != null) {
1999	            active.mNumActive--;

1000	
1001	        // For the SDK sandbox, we start the service on behalf of the client app.
1002	        final int appUid = isSdkSandboxService ? sdkSandboxClientAppUid : r.appInfo.uid;
1003	        final String appPackageName =
1004	                isSdkSandboxService ? sdkSandboxClientAppPackage : r.packageName;
1005	        int appTargetSdkVersion = r.appInfo.targetSdkVersion;
1006	        if (isSdkSandboxService) {
1007	            try {
1008	                appTargetSdkVersion = AppGlobals.getPackageManager().getApplicationInfo(
1009	                        appPackageName, ActivityManagerService.STOCK_PM_FLAGS,
1010	                        userId).targetSdkVersion;
1011	            } catch (RemoteException ignored) {
1012	            }
1013	        }
1014	
1015	        // If we're starting indirectly (e.g. from PendingIntent), figure out whether
1016	        // we're launching into an app in a background state.  This keys off of the same
1017	        // idleness state tracking as e.g. O+ background service start policy.
1018	        final boolean bgLaunch = !mAm.isUidActiveLOSP(appUid);
1019	
1020	        // If the app has strict background restrictions, we treat any bg service
1021	        // start analogously to the legacy-app forced-restrictions case, regardless
1022	        // of its target SDK version.
1023	        boolean forcedStandby = false;
1024	        if (bgLaunch
1025	                && appRestrictedAnyInBackground(appUid, appPackageName)
1026	                && !isTempAllowedByAlarmClock(appUid)
1027	                && !isDeviceProvisioningPackage(appPackageName)) {
1028	            if (DEBUG_FOREGROUND_SERVICE) {
1029	                Slog.d(TAG, "Forcing bg-only service start only for " + r.shortInstanceName
1030	                        + " : bgLaunch=" + bgLaunch + " callerFg=" + callerFg);
1031	            }
1032	            forcedStandby = true;
1033	        }
1034	
1035	        if (fgRequired) {
1036	            logFgsBackgroundStart(r);
1037	            if (!r.isFgsAllowedStart() && isBgFgsRestrictionEnabled(r, callingUid)) {
1038	                String msg = "startForegroundService() not allowed due to "
1039	                        + "mAllowStartForeground false: service "
1040	                        + r.shortInstanceName;
1041	                Slog.w(TAG, msg);
1042	                showFgsBgRestrictedNotificationLocked(r);
1043	                logFGSStateChangeLocked(r,
1044	                        FOREGROUND_SERVICE_STATE_CHANGED__STATE__DENIED,
1045	                        0, FGS_STOP_REASON_UNKNOWN, FGS_TYPE_POLICY_CHECK_UNKNOWN,
1046	                        FOREGROUND_SERVICE_STATE_CHANGED__FGS_START_API__FGSSTARTAPI_NA,
1047	                        false /* fgsRestrictionRecalculated */
1048	                );
1049	                if (CompatChanges.isChangeEnabled(FGS_START_EXCEPTION_CHANGE_ID, callingUid)) {
1050	                    throw new ForegroundServiceStartNotAllowedException(msg);
1051	                }
1052	                return null;
1053	            }
1054	        }
1055	
1056	        // If this is a direct-to-foreground start, make sure it is allowed as per the app op.
1057	        boolean forceSilentAbort = false;
1058	        if (fgRequired) {
1059	            final int mode = mAm.getAppOpsManager().checkOpNoThrow(
1060	                    AppOpsManager.OP_START_FOREGROUND, appUid, appPackageName);
1061	            switch (mode) {
1062	                case AppOpsManager.MODE_ALLOWED:
1063	                case AppOpsManager.MODE_DEFAULT:
1064	                    // All okay.
1065	                    break;
1066	                case AppOpsManager.MODE_IGNORED:
1067	                    // Not allowed, fall back to normal start service, failing siliently
1068	                    // if background check restricts that.
1069	                    Slog.w(TAG, "startForegroundService not allowed due to app op: service "
1070	                            + service + " to " + r.shortInstanceName
1071	                            + " from pid=" + callingPid + " uid=" + callingUid
1072	                            + " pkg=" + callingPackage);
1073	                    fgRequired = false;
1074	                    forceSilentAbort = true;
1075	                    break;
1076	                default:
1077	                    return new ComponentName("!!", "foreground not allowed as per app op");
1078	            }
1079	        }
1080	
1081	        // If this isn't a direct-to-foreground start, check our ability to kick off an
1082	        // arbitrary service.
1083	        if (forcedStandby || (!r.startRequested && !fgRequired)) {
1084	            // Before going further -- if this app is not allowed to start services in the
1085	            // background, then at this point we aren't going to let it period.
1086	            final int allowed = mAm.getAppStartModeLOSP(appUid, appPackageName, appTargetSdkVersion,
1087	                    callingPid, false, false, forcedStandby);
1088	            if (allowed != ActivityManager.APP_START_MODE_NORMAL) {
1089	                Slog.w(TAG, "Background start not allowed: service "
1090	                        + service + " to " + r.shortInstanceName
1091	                        + " from pid=" + callingPid + " uid=" + callingUid
1092	                        + " pkg=" + callingPackage + " startFg?=" + fgRequired);
1093	                if (allowed == ActivityManager.APP_START_MODE_DELAYED || forceSilentAbort) {
1094	                    // In this case we are silently disabling the app, to disrupt as
1095	                    // little as possible existing apps.
1096	                    return null;
1097	                }
1098	                if (forcedStandby) {
1099	                    // This is an O+ app, but we might be here because the user has placed
1100	                    // it under strict background restrictions.  Don't punish the app if it's
1101	                    // trying to do the right thing but we're denying it for that reason.
1102	                    if (fgRequired) {
1103	                        if (DEBUG_BACKGROUND_CHECK) {
1104	                            Slog.v(TAG, "Silently dropping foreground service launch due to FAS");
1105	                        }
1106	                        return null;
1107	                    }
1108	                }
1109	                // This app knows it is in the new model where this operation is not
1110	                // allowed, so tell it what has happened.
1111	                UidRecord uidRec = mAm.mProcessList.getUidRecordLOSP(appUid);
1112	                return new ComponentName("?", "app is in background uid " + uidRec);
1113	            }
1114	        }
1115	
1116	        // At this point we've applied allowed-to-start policy based on whether this was
1117	        // an ordinary startService() or a startForegroundService().  Now, only require that
1118	        // the app follow through on the startForegroundService() -> startForeground()
1119	        // contract if it actually targets O+.
1120	        if (appTargetSdkVersion < Build.VERSION_CODES.O && fgRequired) {
1121	            if (DEBUG_BACKGROUND_CHECK || DEBUG_FOREGROUND_SERVICE) {
1122	                Slog.i(TAG, "startForegroundService() but host targets "
1123	                        + appTargetSdkVersion + " - not requiring startForeground()");
1124	            }
1125	            fgRequired = false;
1126	        }
1127	
1128	        final ProcessRecord callingApp;
1129	        synchronized (mAm.mPidsSelfLocked) {
1130	            callingApp = mAm.mPidsSelfLocked.get(callingPid);
1131	        }
1132	        final String callingProcessName = callingApp != null
1133	                ? callingApp.processName : callingPackage;
1134	        final int callingProcessState =
1135	                callingApp != null && callingApp.getThread() != null && !callingApp.isKilled()
1136	                ? callingApp.mState.getCurProcState() : ActivityManager.PROCESS_STATE_UNKNOWN;
1137	        r.updateProcessStateOnRequest();
1138	
1139	        // The package could be frozen (meaning it's doing surgery), defer the actual
1140	        // start until the package is unfrozen.
1141	        if (deferServiceBringupIfFrozenLocked(r, service, callingPackage, callingFeatureId,
1142	                callingUid, callingPid, callingProcessName,
1143	                callingProcessState, fgRequired, callerFg, userId,
1144	                backgroundStartPrivileges, false, null)) {
1145	            return null;
1146	        }
1147	
1148	        // If permissions need a review before any of the app components can run,
1149	        // we do not start the service and launch a review activity if the calling app
1150	        // is in the foreground passing it a pending intent to start the service when
1151	        // review is completed.
1152	
1153	        // XXX This is not dealing with fgRequired!
1154	        if (!requestStartTargetPermissionsReviewIfNeededLocked(r, callingPackage, callingFeatureId,
1155	                callingUid, service, callerFg, userId, false, null)) {
1156	            return null;
1157	        }
1158	
1159	        // If what the client try to start/connect was an alias, then we need to return the
1160	        // alias component name to the client, not the "target" component name, which is
1161	        // what realResult contains.
1162	        final ComponentName realResult =
1163	                startServiceInnerLocked(r, service, callingUid, callingPid,
1164	                        callingProcessName, callingProcessState,
1165	                        fgRequired, callerFg,
1166	                        backgroundStartPrivileges, callingPackage);
1167	        if (res.aliasComponent != null
1168	                && !realResult.getPackageName().startsWith("!")
1169	                && !realResult.getPackageName().startsWith("?")) {
1170	            return res.aliasComponent;
1171	        } else {
1172	            return realResult;
1173	        }
1174	    }
