1188	    private ComponentName startServiceInnerLocked(ServiceRecord r, Intent service,
1189	            int callingUid, int callingPid, String callingProcessName,
1190	            int callingProcessState, boolean fgRequired, boolean callerFg,
1191	            BackgroundStartPrivileges backgroundStartPrivileges, String callingPackage)
1192	            throws TransactionTooLargeException {
1193	        NeededUriGrants neededGrants = mAm.mUgmInternal.checkGrantUriPermissionFromIntent(
1194	                service, callingUid, r.packageName, r.userId);
1195	        if (unscheduleServiceRestartLocked(r, callingUid, false)) {
1196	            if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "START SERVICE WHILE RESTART PENDING: " + r);
1197	        }
1198	        final boolean wasStartRequested = r.startRequested;
1199	        mAm.mProcessStateController.setServiceLastActivityTime(r, SystemClock.uptimeMillis());
1200	        mAm.mProcessStateController.setStartRequested(r, true);
1201	        r.delayedStop = false;
1202	        r.fgRequired = fgRequired;
1203	        r.pendingStarts.add(new ServiceRecord.StartItem(r, false, r.makeNextStartId(),
1204	                service, neededGrants, callingUid, callingProcessName, callingPackage,
1205	                callingProcessState));
1206	
1207	        // We want to allow scheduling user-initiated jobs when the app is running a
1208	        // foreground service that was started in the same conditions that allows for scheduling
1209	        // UI jobs. More explicitly, we want to allow scheduling UI jobs when the app is running
1210	        // an FGS that started when the app was in the TOP or a BAL-approved state.
1211	        final boolean isFgs = r.isForeground || r.fgRequired;
1212	        if (isFgs) {
1213	            // As of Android UDC, the conditions required for the while-in-use permissions
1214	            // are the same conditions that we want, so we piggyback on that logic.
1215	            // Use that as a shortcut if possible to avoid having to recheck all the conditions.
1216	            final boolean whileInUseAllowsUiJobScheduling =
1217	                    ActivityManagerService.doesReasonCodeAllowSchedulingUserInitiatedJobs(
1218	                            r.getFgsAllowWiu_forStart(), callingUid);
1219	            r.updateAllowUiJobScheduling(whileInUseAllowsUiJobScheduling
1220	                    || mAm.canScheduleUserInitiatedJobs(callingUid, callingPid, callingPackage));
1221	        } else {
1222	            r.updateAllowUiJobScheduling(false);
1223	        }
1224	
1225	        if (fgRequired) {
1226	            // We are now effectively running a foreground service.
1227	            synchronized (mAm.mProcessStats.mLock) {
1228	                final ServiceState stracker = r.getTracker();
1229	                if (stracker != null) {
1230	                    stracker.setForeground(true, mAm.mProcessStats.getMemFactorLocked(),
1231	                            SystemClock.uptimeMillis()); // Use current time, not lastActivity.
1232	                }
1233	            }
1234	            mAm.mAppOpsService.startOperation(AppOpsManager.getToken(mAm.mAppOpsService),
1235	                    AppOpsManager.OP_START_FOREGROUND, r.appInfo.uid, r.packageName, null,
1236	                    true, false, null, false, AppOpsManager.ATTRIBUTION_FLAGS_NONE,
1237	                    AppOpsManager.ATTRIBUTION_CHAIN_ID_NONE);
1238	        }
1239	
1240	        final ServiceMap smap = getServiceMapLocked(r.userId);
1241	        boolean addToStarting = false;
1242	        if (!callerFg && !fgRequired && r.app == null
1243	                && mAm.mUserController.hasStartedUserState(r.userId)) {
1244	            ProcessRecord proc = mAm.getProcessRecordLocked(r.processName, r.appInfo.uid);
1245	            if (proc == null || proc.mState.getCurProcState() > PROCESS_STATE_RECEIVER) {
1246	                // If this is not coming from a foreground caller, then we may want
1247	                // to delay the start if there are already other background services
1248	                // that are starting.  This is to avoid process start spam when lots
1249	                // of applications are all handling things like connectivity broadcasts.
1250	                // We only do this for cached processes, because otherwise an application
1251	                // can have assumptions about calling startService() for a service to run
1252	                // in its own process, and for that process to not be killed before the
1253	                // service is started.  This is especially the case for receivers, which
1254	                // may start a service in onReceive() to do some additional work and have
1255	                // initialized some global state as part of that.
1256	                if (DEBUG_DELAYED_SERVICE) Slog.v(TAG_SERVICE, "Potential start delay of "
1257	                        + r + " in " + proc);
1258	                if (r.delayed) {
1259	                    // This service is already scheduled for a delayed start; just leave
1260	                    // it still waiting.
1261	                    if (DEBUG_DELAYED_STARTS) Slog.v(TAG_SERVICE, "Continuing to delay: " + r);
1262	                    return r.name;
1263	                }
1264	                if (smap.mStartingBackground.size() >= mMaxStartingBackground) {
1265	                    // Something else is starting, delay!
1266	                    Slog.i(TAG_SERVICE, "Delaying start of: " + r);
1267	                    smap.mDelayedStartList.add(r);
1268	                    r.delayed = true;
1269	                    return r.name;
1270	                }
1271	                if (DEBUG_DELAYED_STARTS) Slog.v(TAG_SERVICE, "Not delaying: " + r);
1272	                addToStarting = true;
1273	            } else if (proc.mState.getCurProcState() >= ActivityManager.PROCESS_STATE_SERVICE) {
1274	                // We slightly loosen when we will enqueue this new service as a background
1275	                // starting service we are waiting for, to also include processes that are
1276	                // currently running other services or receivers.
1277	                addToStarting = true;
1278	                if (DEBUG_DELAYED_STARTS) Slog.v(TAG_SERVICE,
1279	                        "Not delaying, but counting as bg: " + r);
1280	            } else if (DEBUG_DELAYED_STARTS) {
1281	                StringBuilder sb = new StringBuilder(128);
1282	                sb.append("Not potential delay (state=").append(proc.mState.getCurProcState())
1283	                        .append(' ').append(proc.mState.getAdjType());
1284	                String reason = proc.mState.makeAdjReason();
1285	                if (reason != null) {
1286	                    sb.append(' ');
1287	                    sb.append(reason);
1288	                }
1289	                sb.append("): ");
1290	                sb.append(r.toString());
1291	                Slog.v(TAG_SERVICE, sb.toString());
1292	            }
1293	        } else if (DEBUG_DELAYED_STARTS) {
1294	            if (callerFg || fgRequired) {
1295	                Slog.v(TAG_SERVICE, "Not potential delay (callerFg=" + callerFg + " uid="
1296	                        + callingUid + " pid=" + callingPid + " fgRequired=" + fgRequired + "): " + r);
1297	            } else if (r.app != null) {
1298	                Slog.v(TAG_SERVICE, "Not potential delay (cur app=" + r.app + "): " + r);
1299	            } else {
1300	                Slog.v(TAG_SERVICE,
1301	                        "Not potential delay (user " + r.userId + " not started): " + r);
1302	            }
1303	        }
1304	        if (backgroundStartPrivileges.allowsAny()) {
1305	            r.allowBgActivityStartsOnServiceStart(backgroundStartPrivileges);
1306	        }
1307	        ComponentName cmp = startServiceInnerLocked(smap, service, r, callerFg, addToStarting,
1308	                callingUid, callingProcessName, callingProcessState,
1309	                wasStartRequested, callingPackage);
1310	        return cmp;
1311	    }
