1313	    private boolean requestStartTargetPermissionsReviewIfNeededLocked(ServiceRecord r,
1314	            String callingPackage, @Nullable String callingFeatureId, int callingUid,
1315	            Intent service, boolean callerFg, final int userId,
1316	            final boolean isBinding, final IServiceConnection connection) {
1317	        if (mAm.getPackageManagerInternal().isPermissionsReviewRequired(
1318	                r.packageName, r.userId)) {
1319	
1320	            // Show a permission review UI only for starting/binding from a foreground app
1321	            if (!callerFg) {
1322	                Slog.w(TAG, "u" + r.userId
1323	                        + (isBinding ? " Binding" : " Starting") + " a service in package"
1324	                        + r.packageName + " requires a permissions review");
