1328	            final Intent intent = new Intent(Intent.ACTION_REVIEW_PERMISSIONS);
1329	            intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK
1330	                    | Intent.FLAG_ACTIVITY_MULTIPLE_TASK
1331	                    | Intent.FLAG_ACTIVITY_EXCLUDE_FROM_RECENTS);
1332	            intent.putExtra(Intent.EXTRA_PACKAGE_NAME, r.packageName);
1333	
1334	            if (isBinding) {
1335	                RemoteCallback callback = new RemoteCallback(
1336	                        new RemoteCallback.OnResultListener() {
1337	                            @Override
1338	                            public void onResult(Bundle result) {
1339	                                synchronized (mAm) {
