3277	    /**
3278	     * Callback from NotificationManagerService whenever it posts a notification
3279	     * associated with a foreground service.  This is the unified handling point
3280	     * for the disjoint code flows that affect an FGS's notifiation content and
3281	     * visibility, starting with both Service.startForeground() and
3282	     * NotificationManager.notify().
3283	     */
3284	    public void onForegroundServiceNotificationUpdateLocked(boolean shown,
3285	            Notification notification, final int id, final String pkg,
3286	            @UserIdInt final int userId) {
3287	        // If this happens to be a Notification for an FGS still in its deferral period,
3288	        // drop the deferral and make sure our content bookkeeping is up to date.
3289	        for (int i = mPendingFgsNotifications.size() - 1; i >= 0; i--) {
3290	            final ServiceRecord sr = mPendingFgsNotifications.get(i);
3291	            if (userId == sr.userId
3292	                    && id == sr.foregroundId
3293	                    && sr.appInfo.packageName.equals(pkg)) {
3294	                // Found it.  If 'shown' is false, it means that the notification
3295	                // subsystem will not be displaying it yet.
3296	                if (shown) {
3297	                    if (DEBUG_FOREGROUND_SERVICE) {
3298	                        Slog.d(TAG_SERVICE, "Notification shown; canceling deferral of "
3299	                                + sr);
3300	                    }
3301	                    sr.mFgsNotificationShown = true;
3302	                    sr.mFgsNotificationDeferred = false;
3303	                    mPendingFgsNotifications.remove(i);
3304	                } else {
3305	                    if (DEBUG_FOREGROUND_SERVICE) {
3306	                        Slog.d(TAG_SERVICE, "FGS notification deferred for " + sr);
3307	                    }
3308	                }
3309	            }
3310	        }
3311	        // In all cases, make sure to retain the latest notification content for the FGS
3312	        ServiceMap smap = mServiceMap.get(userId);
3313	        if (smap != null) {
3314	            for (int i = 0; i < smap.mServicesByInstanceName.size(); i++) {
3315	                final ServiceRecord sr = smap.mServicesByInstanceName.valueAt(i);
3316	                if (sr.isForeground
3317	                        && id == sr.foregroundId
3318	                        && sr.appInfo.packageName.equals(pkg)) {
3319	                    if (DEBUG_FOREGROUND_SERVICE) {
3320	                        Slog.d(TAG_SERVICE, "Recording shown notification for "
3321	                                + sr);
3322	                    }
3323	                    sr.foregroundNoti = notification;
3324	                }
3325	            }
3326	        }
3327	    }
