3355	    /**
3356	     * For monitoring when {@link #LOGGED_AP_OPS} AppOps occur by an app while it is holding
3357	     * at least one foreground service and is not also in the TOP state.
3358	     * Once the uid no longer holds any foreground services, this callback becomes stale
3359	     * (marked by {@link #isObsoleteLocked()}) and must no longer be used.
3360	     *
3361	     * Methods that end in Locked should only be called while the mAm lock is held.
3362	     */
3363	    private static final class AppOpCallback {
3364	        /** AppOps that should be logged if they occur during a foreground service. */
3365	        private static final int[] LOGGED_AP_OPS = new int[] {
3366	                AppOpsManager.OP_COARSE_LOCATION,
3367	                AppOpsManager.OP_FINE_LOCATION,
3368	                AppOpsManager.OP_RECORD_AUDIO,
3369	                AppOpsManager.OP_CAMERA
3370	        };
3371	
3372	        private final ProcessRecord mProcessRecord;
3373	
3374	        /** Count of acceptances per appop (for LOGGED_AP_OPS) during this fgs session. */
3375	        @GuardedBy("mCounterLock")
3376	        private final SparseIntArray mAcceptedOps = new SparseIntArray();
3377	        /** Count of rejections per appop (for LOGGED_AP_OPS) during this fgs session. */
3378	        @GuardedBy("mCounterLock")
3379	        private final SparseIntArray mRejectedOps = new SparseIntArray();
3380	
3381	        /** Lock for the purposes of mAcceptedOps and mRejectedOps. */
3382	        private final Object mCounterLock = new Object();
3383	
3384	        /**
3385	         * AppOp Mode (e.g. {@link AppOpsManager#MODE_ALLOWED} per op.
3386	         * This currently cannot change without the process being killed, so they are constants.
3387	         */
3388	        private final SparseIntArray mAppOpModes = new SparseIntArray();
3389	
3390	        /**
3391	         * Number of foreground services currently associated with this AppOpCallback (i.e.
3392	         * currently held for this uid).
3393	         */
3394	        @GuardedBy("mAm")
3395	        private int mNumFgs = 0;
3396	
3397	        /**
3398	         * Indicates that this Object is stale and must not be used.
3399	         * Specifically, when mNumFgs decreases down to 0, the callbacks will be unregistered and
3400	         * this AppOpCallback is unusable.
3401	         */
3402	        @GuardedBy("mAm")
3403	        private boolean mDestroyed = false;
3404	
3405	        private final AppOpsManager mAppOpsManager;
3406	
3407	        AppOpCallback(@NonNull ProcessRecord r, @NonNull AppOpsManager appOpsManager) {
3408	            mProcessRecord = r;
3409	            mAppOpsManager = appOpsManager;
3410	            for (int op : LOGGED_AP_OPS) {
3411	                int mode = appOpsManager.unsafeCheckOpRawNoThrow(op, r.uid, r.info.packageName);
3412	                mAppOpModes.put(op, mode);
3413	            }
3414	        }
3415	
3416	        private final AppOpsManager.OnOpNotedInternalListener mOpNotedCallback =
3417	                new AppOpsManager.OnOpNotedInternalListener() {
3418	                    @Override
3419	                    public void onOpNoted(int op, int uid, String pkgName,
3420	                            String attributionTag, int flags, int result) {
3421	                        incrementOpCountIfNeeded(op, uid, result);
3422	                    }
3423	        };
3424	
3425	        private final AppOpsManager.OnOpStartedListener mOpStartedCallback =
3426	                new AppOpsManager.OnOpStartedListener() {
3427	                    @Override
3428	                    public void onOpStarted(int op, int uid, String pkgName,
3429	                            String attributionTag, int flags,
3430	                            int result) {
3431	                        incrementOpCountIfNeeded(op, uid, result);
3432	                    }
3433	        };
3434	
3435	        private void incrementOpCountIfNeeded(int op, int uid, @AppOpsManager.Mode int result) {
3436	            if (uid == mProcessRecord.uid && isNotTop()) {
3437	                incrementOpCount(op, result == AppOpsManager.MODE_ALLOWED);
3438	            }
3439	        }
3440	
3441	        private boolean isNotTop() {
3442	            return mProcessRecord.mState.getCurProcState() != PROCESS_STATE_TOP;
3443	        }
3444	
3445	        private void incrementOpCount(int op, boolean allowed) {
3446	            synchronized (mCounterLock) {
3447	                final SparseIntArray counter = allowed ? mAcceptedOps : mRejectedOps;
3448	                final int index = counter.indexOfKey(op);
3449	                if (index < 0) {
3450	                    counter.put(op, 1);
3451	                } else {
3452	                    counter.setValueAt(index, counter.valueAt(index) + 1);
3453	                }
3454	            }
3455	        }
3456	
3457	        void registerLocked() {
3458	            if (isObsoleteLocked()) {
3459	                Slog.wtf(TAG, "Trying to register on a stale AppOpCallback.");
3460	                return;
3461	            }
3462	            mNumFgs++;
3463	            if (mNumFgs == 1) {
3464	                mAppOpsManager.startWatchingNoted(LOGGED_AP_OPS, mOpNotedCallback);
3465	                mAppOpsManager.startWatchingStarted(LOGGED_AP_OPS, mOpStartedCallback);
3466	            }
3467	        }
3468	
3469	        void unregisterLocked() {
3470	            mNumFgs--;
3471	            if (mNumFgs <= 0) {
3472	                mDestroyed = true;
3473	                logFinalValues();
3474	                mAppOpsManager.stopWatchingNoted(mOpNotedCallback);
3475	                mAppOpsManager.stopWatchingStarted(mOpStartedCallback);
3476	            }
3477	        }
3478	
3479	        /**
3480	         * Indicates that all foreground services for this uid are now over and the callback is
3481	         * stale and must never be used again.
3482	         */
3483	        boolean isObsoleteLocked() {
3484	            return mDestroyed;
3485	        }
3486	
3487	        private void logFinalValues() {
3488	            synchronized (mCounterLock) {
3489	                for (int op : LOGGED_AP_OPS) {
3490	                    final int acceptances = mAcceptedOps.get(op);
3491	                    final int rejections = mRejectedOps.get(op);
3492	                    if (acceptances > 0 ||  rejections > 0) {
3493	                        FrameworkStatsLog.write(
3494	                                FrameworkStatsLog.FOREGROUND_SERVICE_APP_OP_SESSION_ENDED,
3495	                                mProcessRecord.uid, op,
3496	                                modeToEnum(mAppOpModes.get(op)),
3497	                                acceptances, rejections
3498	                        );
3499	                    }
3500	                }
3501	            }
3502	        }
3503	
3504	        /** Maps AppOp mode to atoms.proto enum. */
3505	        private static int modeToEnum(int mode) {
3506	            switch (mode) {
3507	                case AppOpsManager.MODE_ALLOWED: return FrameworkStatsLog
3508	                        .FOREGROUND_SERVICE_APP_OP_SESSION_ENDED__APP_OP_MODE__MODE_ALLOWED;
3509	                case AppOpsManager.MODE_IGNORED: return FrameworkStatsLog
3510	                        .FOREGROUND_SERVICE_APP_OP_SESSION_ENDED__APP_OP_MODE__MODE_IGNORED;
3511	                case AppOpsManager.MODE_FOREGROUND: return FrameworkStatsLog
3512	                        .FOREGROUND_SERVICE_APP_OP_SESSION_ENDED__APP_OP_MODE__MODE_FOREGROUND;
3513	                default: return FrameworkStatsLog
3514	                        .FOREGROUND_SERVICE_APP_OP_SESSION_ENDED__APP_OP_MODE__MODE_UNKNOWN;
3515	            }
3516	        }
3517	    }
