3519	    private void cancelForegroundNotificationLocked(ServiceRecord r) {
3520	        if (r.foregroundNoti != null) {
3521	            // First check to see if this app has any other active foreground services
3522	            // with the same notification ID.  If so, we shouldn't actually cancel it,
3523	            // because that would wipe away the notification that still needs to be shown
3524	            // due the other service.
3525	            ServiceMap sm = getServiceMapLocked(r.userId);
3526	            if (sm != null) {
3527	                for (int i = sm.mServicesByInstanceName.size() - 1; i >= 0; i--) {
3528	                    ServiceRecord other = sm.mServicesByInstanceName.valueAt(i);
3529	                    if (other != r
3530	                            && other.isForeground
3531	                            && other.foregroundId == r.foregroundId
3532	                            && other.packageName.equals(r.packageName)) {
3533	                        if (DEBUG_FOREGROUND_SERVICE) {
3534	                            Slog.i(TAG_SERVICE, "FGS notification for " + r
3535	                                    + " shared by " + other
3536	                                    + " (isForeground=" + other.isForeground + ")"
3537	                                    + " - NOT cancelling");
3538	                        }
3539	                        return;
3540	                    }
3541	                }
3542	            }
3543	            r.cancelNotification();
3544	        }
3545	    }
