4018	    void updateServiceConnectionActivitiesLocked(ProcessServiceRecord clientPsr) {
4019	        ArraySet<ProcessRecord> updatedProcesses = null;
4020	        for (int i = 0; i < clientPsr.numberOfConnections(); i++) {
4021	            final ConnectionRecord conn = clientPsr.getConnectionAt(i);
4022	            final ProcessRecord proc = conn.binding.service.app;
4023	            if (proc == null || proc == clientPsr.mApp) {
4024	                continue;
4025	            } else if (updatedProcesses == null) {
4026	                updatedProcesses = new ArraySet<>();
4027	            } else if (updatedProcesses.contains(proc)) {
4028	                continue;
4029	            }
4030	            updatedProcesses.add(proc);
4031	            updateServiceClientActivitiesLocked(proc.mServices, null, false);
4032	        }
4033	    }
