4074	    int bindServiceLocked(IApplicationThread caller, IBinder token, Intent service,
4075	            String resolvedType, final IServiceConnection connection, long flags,
4076	            String instanceName, boolean isSdkSandboxService, int sdkSandboxClientAppUid,
4077	            String sdkSandboxClientAppPackage, IApplicationThread sdkSandboxClientApplicationThread,
4078	            String callingPackage, final int userId)
4079	            throws TransactionTooLargeException {
4080	        if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "bindService: " + service
4081	                + " type=" + resolvedType + " conn=" + connection.asBinder()
4082	                + " flags=0x" + Long.toHexString(flags));
4083	        final int callingPid = mAm.mInjector.getCallingPid();
4084	        final int callingUid = mAm.mInjector.getCallingUid();
4085	        final ProcessRecord callerApp = mAm.getRecordForAppLOSP(caller);
4086	        if (callerApp == null) {
4087	            throw new SecurityException(
4088	                    "Unable to find app for caller " + caller
4089	                    + " (pid=" + callingPid
4090	                    + ") when binding service " + service);
4091	        }
4092	
4093	        ActivityServiceConnectionsHolder<ConnectionRecord> activity = null;
4094	        if (token != null) {
4095	            activity = mAm.mAtmInternal.getServiceConnectionsHolder(token);
4096	            if (activity == null) {
4097	                Slog.w(TAG, "Binding with unknown activity: " + token);
4098	                return 0;
4099	            }
4100	        }
4101	
4102	        int clientLabel = 0;
4103	        PendingIntent clientIntent = null;
4104	        final boolean isCallerSystem = callerApp.info.uid == Process.SYSTEM_UID;
4105	
4106	        if (isCallerSystem) {
4107	            // Hacky kind of thing -- allow system stuff to tell us
4108	            // what they are, so we can report this elsewhere for
4109	            // others to know why certain services are running.
4110	            service.setDefusable(true);
4111	            clientIntent = service.getParcelableExtra(Intent.EXTRA_CLIENT_INTENT);
4112	            if (clientIntent != null) {
4113	                clientLabel = service.getIntExtra(Intent.EXTRA_CLIENT_LABEL, 0);
4114	                if (clientLabel != 0) {
4115	                    // There are no useful extras in the intent, trash them.
4116	                    // System code calling with this stuff just needs to know
4117	                    // this will happen.
4118	                    service = service.cloneFilter();
4119	                }
4120	            }
4121	        }
4122	
4123	        if ((flags&Context.BIND_TREAT_LIKE_ACTIVITY) != 0) {
4124	            mAm.enforceCallingPermission(android.Manifest.permission.MANAGE_ACTIVITY_TASKS,
4125	                    "BIND_TREAT_LIKE_ACTIVITY");
4126	        }
4127	
4128	        if ((flags & Context.BIND_SCHEDULE_LIKE_TOP_APP) != 0 && !isCallerSystem) {
4129	            throw new SecurityException("Non-system caller (pid=" + callingPid
4130	                    + ") set BIND_SCHEDULE_LIKE_TOP_APP when binding service " + service);
4131	        }
4132	
4133	        if ((flags & BIND_ALLOW_WHITELIST_MANAGEMENT) != 0 && !isCallerSystem) {
4134	            throw new SecurityException(
4135	                    "Non-system caller " + caller + " (pid=" + callingPid
4136	                    + ") set BIND_ALLOW_WHITELIST_MANAGEMENT when binding service " + service);
4137	        }
4138	
4139	        if ((flags & Context.BIND_ALLOW_INSTANT) != 0 && !isCallerSystem) {
4140	            throw new SecurityException(
4141	                    "Non-system caller " + caller + " (pid=" + callingPid
4142	                            + ") set BIND_ALLOW_INSTANT when binding service " + service);
4143	        }
4144	
4145	        if ((flags & Context.BIND_ALMOST_PERCEPTIBLE) != 0 && !isCallerSystem) {
4146	            throw new SecurityException("Non-system caller (pid=" + callingPid
4147	                    + ") set BIND_ALMOST_PERCEPTIBLE when binding service " + service);
4148	        }
4149	
4150	        if ((flags & Context.BIND_ALLOW_BACKGROUND_ACTIVITY_STARTS) != 0) {
