4466	    void publishServiceLocked(ServiceRecord r, Intent intent, IBinder service) {
4467	        final long origId = mAm.mInjector.clearCallingIdentity();
4468	        try {
4469	            if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "PUBLISHING " + r
4470	                    + " " + intent + ": " + service);
4471	            if (r != null) {
4472	                Intent.FilterComparison filter
4473	                        = new Intent.FilterComparison(intent);
4474	                IntentBindRecord b = r.bindings.get(filter);
4475	                if (b != null && !b.received) {
4476	                    b.binder = service;
4477	                    b.requested = true;
4478	                    b.received = true;
4479	                    ArrayMap<IBinder, ArrayList<ConnectionRecord>> connections = r.getConnections();
4480	                    for (int conni = connections.size() - 1; conni >= 0; conni--) {
4481	                        ArrayList<ConnectionRecord> clist = connections.valueAt(conni);
4482	                        for (int i=0; i<clist.size(); i++) {
4483	                            ConnectionRecord c = clist.get(i);
4484	                            if (!filter.equals(c.binding.intent.intent)) {
4485	                                if (DEBUG_SERVICE) Slog.v(
4486	                                        TAG_SERVICE, "Not publishing to: " + c);
4487	                                if (DEBUG_SERVICE) Slog.v(
4488	                                        TAG_SERVICE, "Bound intent: " + c.binding.intent.intent);
4489	                                if (DEBUG_SERVICE) Slog.v(
4490	                                        TAG_SERVICE, "Published intent: " + intent);
4491	                                continue;
4492	                            }
4493	                            if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "Publishing to: " + c);
4494	                            // If what the client try to start/connect was an alias, then we need to
4495	                            // pass the alias component name instead to the client.
4496	                            final ComponentName clientSideComponentName =
4497	                                    c.aliasComponent != null ? c.aliasComponent : r.name;
4498	                            try {
4499	                                c.conn.connected(clientSideComponentName, service, false);
4500	                            } catch (Exception e) {
4501	                                Slog.w(TAG, "Failure sending service " + r.shortInstanceName
4502	                                      + " to connection " + c.conn.asBinder()
4503	                                      + " (in " + c.binding.client.processName + ")", e);
4504	                            }
4505	                        }
4506	                    }
4507	                }
4508	
4509	                serviceDoneExecutingLocked(r, mDestroyingServices.contains(r), false, false,
