4518	    void updateServiceGroupLocked(IServiceConnection connection, int group, int importance) {
4519	        final IBinder binder = connection.asBinder();
4520	        if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "updateServiceGroup: conn=" + binder);
4521	        final ArrayList<ConnectionRecord> clist = mServiceConnections.get(binder);
4522	        if (clist == null) {
4523	            throw new IllegalArgumentException("Could not find connection for "
4524	                    + connection.asBinder());
4525	        }
4526	        for (int i = clist.size() - 1; i >= 0; i--) {
4527	            final ConnectionRecord crec = clist.get(i);
4528	            final ServiceRecord srec = crec.binding.service;
4529	            if (srec != null && (srec.serviceInfo.flags & ServiceInfo.FLAG_ISOLATED_PROCESS) != 0) {
4530	                if (srec.app != null) {
4531	                    final ProcessServiceRecord psr = srec.app.mServices;
4532	                    if (group > 0) {
4533	                        psr.setConnectionService(srec);
4534	                        psr.setConnectionGroup(group);
4535	                        psr.setConnectionImportance(importance);
4536	                    } else {
4537	                        psr.setConnectionService(null);
4538	                        psr.setConnectionGroup(0);
4539	                        psr.setConnectionImportance(0);
4540	                    }
4541	                } else {
4542	                    if (group > 0) {
4543	                        srec.pendingConnectionGroup = group;
4544	                        srec.pendingConnectionImportance = importance;
4545	                    } else {
4546	                        srec.pendingConnectionGroup = 0;
4547	                        srec.pendingConnectionImportance = 0;
4548	                    }
4549	                }
4550	            }
4551	        }
4552	    }
