4554	    boolean unbindServiceLocked(IServiceConnection connection) {
4555	        IBinder binder = connection.asBinder();
4556	        if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "unbindService: conn=" + binder);
4557	        ArrayList<ConnectionRecord> clist = mServiceConnections.get(binder);
4558	        if (clist == null) {
4559	            Slog.w(TAG, "Unbind failed: could not find connection for "
4560	                  + connection.asBinder());
4561	            return false;
4562	        }
4563	
4564	        final int callingPid = mAm.mInjector.getCallingPid();
4565	        final long origId = mAm.mInjector.clearCallingIdentity();
4566	        try {
4567	            if (Trace.isTagEnabled(Trace.TRACE_TAG_ACTIVITY_MANAGER)) {
4568	                String info;
4569	                if (clist.size() > 0) {
4570	                    final ConnectionRecord r = clist.get(0);
4571	                    info = r.binding.service.shortInstanceName + " from " + r.clientProcessName;
4572	                } else {
4573	                    info = Integer.toString(callingPid);
4574	                }
4575	                Trace.traceBegin(Trace.TRACE_TAG_ACTIVITY_MANAGER, "unbindServiceLocked: " + info);
4576	            }
4577	
4578	            boolean needOomAdj = false;
4579	            while (clist.size() > 0) {
4580	                ConnectionRecord r = clist.get(0);
4581	                int serviceBindingOomAdjPolicy = removeConnectionLocked(r, null, null, true);
4582	                if (clist.size() > 0 && clist.get(0) == r) {
4583	                    // In case it didn't get removed above, do it now.
4584	                    Slog.wtf(TAG, "Connection " + r + " not removed for binder " + binder);
