5154	        // For b/34123235: Services within the system server won't start until SystemServer
5155	        // does Looper.loop(), so we shouldn't try to start/bind to them too early in the boot
5156	        // process. However, since there's a little point of showing the ANR dialog in that case,
5157	        // let's suppress the timeout until PHASE_THIRD_PARTY_APPS_CAN_START.
5158	        //
5159	        // (Note there are multiple services start at PHASE_THIRD_PARTY_APPS_CAN_START too,
5160	        // which technically could also trigger this timeout if there's a system server
5161	        // that takes a long time to handle PHASE_THIRD_PARTY_APPS_CAN_START, but that shouldn't
5162	        // happen.)
5163	        boolean timeoutNeeded = true;
5164	        if ((mAm.mBootPhase < SystemService.PHASE_THIRD_PARTY_APPS_CAN_START)
5165	                && (r.app != null) && (r.app.getPid() == ActivityManagerService.MY_PID)) {
5166	
