5173	        final boolean shouldSkipTimeout = skipTimeoutIfPossible && r.app != null
5174	                && (r.app.mOptRecord.isPendingFreeze() || r.app.mOptRecord.isFrozen());
5175	
5176	        ProcessServiceRecord psr;
5177	        if (r.executeNesting == 0) {
5178	            r.executeFg = fg;
5179	            synchronized (mAm.mProcessStats.mLock) {
5180	                final ServiceState stracker = r.getTracker();
5181	                if (stracker != null) {
