5511	    /**
5512	     * Rescan the list of pending restarts, reschedule them if needed.
5513	     *
5514	     * @param extraRestartTimeBetween The extra interval between restarts.
5515	     * @param minRestartTimeBetween The minimal interval between restarts.
5516	     * @param reason The human-readable text about why we're doing rescheduling.
5517	     * @param now The uptimeMillis
5518	     */
5519	    @GuardedBy("mAm")
5520	    void rescheduleServiceRestartIfPossibleLocked(long extraRestartTimeBetween,
5521	            long minRestartTimeBetween, @NonNull String reason, @UptimeMillisLong long now) {
5522	        final long restartTimeBetween = extraRestartTimeBetween + minRestartTimeBetween;
5523	        final long spanForInsertOne = restartTimeBetween * 2; // Min space to insert a restart.
5524	
5525	        long lastRestartTime = now;
5526	        int lastRestartTimePos = -1; // The list index where the "lastRestartTime" comes from.
5527	        for (int i = 0, size = mRestartingServices.size(); i < size; i++) {
5528	            final ServiceRecord r = mRestartingServices.get(i);
5529	            if ((r.serviceInfo.applicationInfo.flags & ApplicationInfo.FLAG_PERSISTENT) != 0
5530	                    || !isServiceRestartBackoffEnabledLocked(r.packageName)) {
5531	                lastRestartTime = r.nextRestartTime;
5532	                lastRestartTimePos = i;
5533	                continue;
5534	            }
5535	            if (lastRestartTime + restartTimeBetween <= r.mEarliestRestartTime) {
5536	                // Bounded by the earliest restart time, honor it; but we also need to
5537	                // check if the interval between the earlist and its prior one is enough or not.
5538	                r.nextRestartTime = Math.max(now, Math.max(r.mEarliestRestartTime, i > 0
5539	                        ? mRestartingServices.get(i - 1).nextRestartTime + restartTimeBetween
5540	                        : 0));
5541	            } else {
5542	                if (lastRestartTime <= now) {
5543	                    // It hasn't moved, this is the first one (besides persistent process),
5544	                    // we don't need to insert the minRestartTimeBetween for it, but need
5545	                    // the extraRestartTimeBetween still.
5546	                    r.nextRestartTime = Math.max(now, Math.max(r.mEarliestRestartTime,
5547	                            r.mRestartSchedulingTime + extraRestartTimeBetween));
5548	                } else {
5549	                    r.nextRestartTime = Math.max(now, lastRestartTime + restartTimeBetween);
5550	                }
5551	                if (i > lastRestartTimePos + 1) {
5552	                    // Move the current service record ahead in the list.
5553	                    mRestartingServices.remove(i);
5554	                    mRestartingServices.add(lastRestartTimePos + 1, r);
5555	                }
5556	            }
5557	            // Find the next available slot to insert one if there is any
5558	            for (int j = lastRestartTimePos + 1; j <= i; j++) {
5559	                final ServiceRecord r2 = mRestartingServices.get(j);
5560	                final long timeInBetween = r2.nextRestartTime - (j == 0 ? lastRestartTime
5561	                        : mRestartingServices.get(j - 1).nextRestartTime);
5562	                if (timeInBetween >= spanForInsertOne) {
5563	                    break;
5564	                }
5565	                lastRestartTime = r2.nextRestartTime;
5566	                lastRestartTimePos = j;
5567	            }
5568	            r.restartDelay = r.nextRestartTime - now;
5569	            performScheduleRestartLocked(r, "Rescheduling", reason, now);
5570	        }
5571	    }
