5619	    long getExtraRestartTimeInBetweenLocked() {
5620	        if (!mAm.mConstants.mEnableExtraServiceRestartDelayOnMemPressure) {
5621	            return 0;
5622	        }
5623	        final @MemFactor int memFactor = mAm.mAppProfiler.getLastMemoryLevelLocked();
5624	        return mAm.mConstants.mExtraServiceRestartDelayOnMemPressure[memFactor];
