5627	    final void performServiceRestartLocked(ServiceRecord r) {
5628	        if (!mRestartingServices.contains(r)) {
5629	            return;
5630	        }
5631	        if (!isServiceNeededLocked(r, false, false)) {
5632	            // Paranoia: is this service actually needed?  In theory a service that is not
5633	            // needed should never remain on the restart list.  In practice...  well, there
5634	            // have been bugs where this happens, and bad things happen because the process
5635	            // ends up just being cached, so quickly killed, then restarted again and again.
5636	            // Let's not let that happen.
5637	            Slog.wtf(TAG, "Restarting service that is not needed: " + r);
5638	            return;
5639	        }
5640	        try {
5641	            bringUpServiceLocked(r, r.intent.getIntent().getFlags(), r.createdFromFg, true, false,
5642	                    false, true, SERVICE_BIND_OOMADJ_POLICY_LEGACY);
5643	        } catch (TransactionTooLargeException e) {
5644	            // Ignore, it's been logged and nothing upstack cares.
5645	        } finally {
5646	            /* Will be a no-op if nothing pending */
5647	            mAm.updateOomAdjPendingTargetsLocked(OOM_ADJ_REASON_START_SERVICE);
5648	        }
5649	    }
