5670	    private void clearRestartingIfNeededLocked(ServiceRecord r) {
5671	        if (r.restartTracker != null) {
5672	            // If this is the last restarting record with this tracker, then clear
5673	            // the tracker's restarting state.
5674	            boolean stillTracking = false;
5675	            for (int i=mRestartingServices.size()-1; i>=0; i--) {
5676	                if (mRestartingServices.get(i).restartTracker == r.restartTracker) {
5677	                    stillTracking = true;
5678	                    break;
5679	                }
5680	            }
5681	            if (!stillTracking) {
5682	                synchronized (mAm.mProcessStats.mLock) {
5683	                    r.restartTracker.setRestarting(false, mAm.mProcessStats.getMemFactorLocked(),
5684	                            SystemClock.uptimeMillis());
5685	                }
5686	                r.restartTracker = null;
5687	            }
5688	        }
5689	    }
