5691	    /**
5692	     * Toggle service restart backoff policy, used by {@link ActivityManagerShellCommand}.
5693	     */
5694	    @GuardedBy("mAm")
5695	    void setServiceRestartBackoffEnabledLocked(@NonNull String packageName, boolean enable,
5696	            @NonNull String reason) {
5697	        if (!enable) {
5698	            if (mRestartBackoffDisabledPackages.contains(packageName)) {
5699	                // Already disabled, do nothing.
5700	                return;
5701	            }
5702	            mRestartBackoffDisabledPackages.add(packageName);
5703	
5704	            final long now = SystemClock.uptimeMillis();
5705	            for (int i = 0, size = mRestartingServices.size(); i < size; i++) {
5706	                final ServiceRecord r = mRestartingServices.get(i);
5707	                if (TextUtils.equals(r.packageName, packageName)) {
5708	                    final long remaining = r.nextRestartTime - now;
5709	                    if (remaining > mAm.mConstants.SERVICE_RESTART_DURATION) {
5710	                        r.restartDelay = mAm.mConstants.SERVICE_RESTART_DURATION;
5711	                        r.nextRestartTime = now + r.restartDelay;
5712	                        performScheduleRestartLocked(r, "Rescheduling", reason, now);
5713	                    }
5714	                }
5715	                // mRestartingServices is sorted by nextRestartTime.
5716	                Collections.sort(mRestartingServices,
5717	                        (a, b) -> (int) (a.nextRestartTime - b.nextRestartTime));
5718	            }
5719	        } else {
5720	            removeServiceRestartBackoffEnabledLocked(packageName);
5721	            // For the simplicity, we are not going to reschedule its pending restarts
5722	            // when we turn the backoff policy back on.
5723	        }
5724	    }
