5757	    private String bringUpServiceInnerLocked(ServiceRecord r, int intentFlags, boolean execInFg,
5758	            boolean whileRestarting, boolean permissionsReviewRequired, boolean packageFrozen,
5759	            boolean enqueueOomAdj, @ServiceBindingOomAdjPolicy int serviceBindingOomAdjPolicy)
5760	            throws TransactionTooLargeException {
5761	        if (r.app != null && r.app.isThreadReady()) {
5762	            r.updateOomAdjSeq();
5763	            sendServiceArgsLocked(r, execInFg, false);
5764	            return null;
5765	        }
5766	
5767	        if (!whileRestarting && mRestartingServices.contains(r)) {
5768	            // If waiting for a restart, then do nothing.
5769	            return null;
5770	        }
5771	
5772	        final long startTimeNs = SystemClock.elapsedRealtimeNanos();
5773	
5774	        if (DEBUG_SERVICE) {
5775	            Slog.v(TAG_SERVICE, "Bringing up " + r + " " + r.intent + " fg=" + r.fgRequired);
5776	        }
5777	
5778	        // We are now bringing the service up, so no longer in the
5779	        // restarting state.
5780	        if (mRestartingServices.remove(r)) {
5781	            clearRestartingIfNeededLocked(r);
5782	        }
5783	
5784	        // Make sure this service is no longer considered delayed, we are starting it now.
5785	        if (r.delayed) {
5786	            if (DEBUG_DELAYED_STARTS) Slog.v(TAG_SERVICE, "REM FR DELAY LIST (bring up): " + r);
5787	            getServiceMapLocked(r.userId).mDelayedStartList.remove(r);
5788	            r.delayed = false;
5789	        }
5790	
5791	        // Make sure that the user who owns this service is started.  If not,
5792	        // we don't want to allow it to run.
5793	        if (!mAm.mUserController.hasStartedUserState(r.userId)) {
5794	            String msg = "Unable to launch app "
5795	                    + r.appInfo.packageName + "/"
5796	                    + r.appInfo.uid + " for service "
5797	                    + r.intent.getIntent() + ": user " + r.userId + " is stopped";
5798	            Slog.w(TAG, msg);
5799	            bringDownServiceLocked(r, enqueueOomAdj);
5800	            return msg;
5801	        }
5802	
5803	        // Report usage if binding is from a different package except for explicitly exempted
5804	        // bindings
5805	        if (!r.appInfo.packageName.equals(r.mRecentCallingPackage)
5806	                && !r.isNotAppComponentUsage) {
5807	            mAm.mUsageStatsService.reportEvent(
5808	                    r.packageName, r.userId, UsageEvents.Event.APP_COMPONENT_USED);
5809	        }
5810	
5811	        try {
5812	            mAm.mPackageManagerInt.notifyComponentUsed(
5813	                    r.packageName, r.userId, r.mRecentCallingPackage, r.toString());
5814	        } catch (IllegalArgumentException e) {
5815	            Slog.w(TAG, "Failed trying to unstop package "
5816	                    + r.packageName + ": " + e);
5817	        }
5818	
5819	        final boolean isolated = (r.serviceInfo.flags&ServiceInfo.FLAG_ISOLATED_PROCESS) != 0;
5820	        final String procName = r.processName;
5821	        HostingRecord hostingRecord = new HostingRecord(
5822	                HostingRecord.HOSTING_TYPE_SERVICE, r.instanceName,
5823	                r.definingPackageName, r.definingUid, r.serviceInfo.processName,
5824	                getHostingRecordTriggerType(r));
5825	        ProcessRecord app;
5826	
5827	        if (!isolated) {
5828	            app = mAm.getProcessRecordLocked(procName, r.appInfo.uid);
5829	            if (DEBUG_MU) Slog.v(TAG_MU, "bringUpServiceLocked: appInfo.uid=" + r.appInfo.uid
5830	                        + " app=" + app);
5831	            if (app != null) {
5832	                final IApplicationThread thread = app.getThread();
5833	                final int pid = app.getPid();
5834	                final UidRecord uidRecord = app.getUidRecord();
5835	                if (app.isThreadReady()) {
5836	                    try {
5837	                        if (Trace.isTagEnabled(Trace.TRACE_TAG_ACTIVITY_MANAGER)) {
5838	                            Trace.traceBegin(Trace.TRACE_TAG_ACTIVITY_MANAGER,
5839	                                    "realStartServiceLocked: " + r.shortInstanceName);
5840	                        }
5841	                        app.addPackage(r.appInfo.packageName, r.appInfo.longVersionCode,
5842	                                mAm.mProcessStats);
5843	                        realStartServiceLocked(r, app, thread, pid, uidRecord, execInFg,
5844	                                enqueueOomAdj, serviceBindingOomAdjPolicy);
5845	                        return null;
5846	                    } catch (TransactionTooLargeException e) {
5847	                        throw e;
5848	                    } catch (RemoteException e) {
5849	                        Slog.w(TAG, "Exception when starting service " + r.shortInstanceName, e);
5850	                    } finally {
5851	                        Trace.traceEnd(Trace.TRACE_TAG_ACTIVITY_MANAGER);
5852	                    }
5853	
5854	                    // If a dead object exception was thrown -- fall through to
5855	                    // restart the application.
5856	                }
5857	            }
5858	        } else {
5859	            if (r.inSharedIsolatedProcess) {
5860	                app = mAm.mProcessList.getSharedIsolatedProcess(procName, r.appInfo.uid,
5861	                        r.appInfo.packageName);
5862	                if (app != null && !app.isKilled()) {
5863	                    final IApplicationThread thread = app.getThread();
5864	                    final int pid = app.getPid();
5865	                    final UidRecord uidRecord = app.getUidRecord();
5866	                    r.isolationHostProc = app;
5867	                    if (app.isThreadReady()) {
5868	                        try {
5869	                            if (Trace.isTagEnabled(Trace.TRACE_TAG_ACTIVITY_MANAGER)) {
5870	                                Trace.traceBegin(Trace.TRACE_TAG_ACTIVITY_MANAGER,
5871	                                        "realStartServiceLocked: " + r.shortInstanceName);
5872	                            }
5873	                            realStartServiceLocked(r, app, thread, pid, uidRecord, execInFg,
5874	                                    enqueueOomAdj, SERVICE_BIND_OOMADJ_POLICY_LEGACY);
5875	                            return null;
5876	                        } catch (TransactionTooLargeException e) {
5877	                            throw e;
5878	                        } catch (RemoteException e) {
5879	                            Slog.w(TAG, "Exception when starting service " + r.shortInstanceName,
5880	                                    e);
5881	                        } finally {
5882	                            Trace.traceEnd(Trace.TRACE_TAG_ACTIVITY_MANAGER);
5883	                        }
5884	                        // If a dead object exception was thrown -- fall through to
5885	                        // restart the application.
5886	                    }
5887	                } else {
5888	                    app = null;
5889	                }
5890	            } else {
5891	                // If this service runs in an isolated process, then each time
5892	                // we call startProcessLocked() we will get a new isolated
5893	                // process, starting another process if we are currently waiting
5894	                // for a previous process to come up.  To deal with this, we store
5895	                // in the service any current isolated process it is running in or
5896	                // waiting to have come up.
5897	                app = r.isolationHostProc;
5898	                if (WebViewZygote.isMultiprocessEnabled()
5899	                        && r.serviceInfo.packageName.equals(WebViewZygote.getPackageName())) {
5900	                    hostingRecord = HostingRecord.byWebviewZygote(r.instanceName,
5901	                            r.definingPackageName,
5902	                            r.definingUid, r.serviceInfo.processName);
5903	                }
5904	                if ((r.serviceInfo.flags & ServiceInfo.FLAG_USE_APP_ZYGOTE) != 0) {
5905	                    hostingRecord = HostingRecord.byAppZygote(r.instanceName, r.definingPackageName,
5906	                            r.definingUid, r.serviceInfo.processName);
5907	                }
5908	            }
5909	        }
5910	
5911	        // Not running -- get it started, and enqueue this service record
5912	        // to be executed when the app comes up.
5913	        if (app == null && !permissionsReviewRequired && !packageFrozen) {
5914	            // TODO (chriswailes): Change the Zygote policy flags based on if the launch-for-service
5915	            //  was initiated from a notification tap or not.
5916	            if (r.isSdkSandbox) {
5917	                final int uid = Process.toSdkSandboxUid(r.sdkSandboxClientAppUid);
5918	                app = mAm.startSdkSandboxProcessLocked(procName, r.appInfo, true, intentFlags,
5919	                        hostingRecord, ZYGOTE_POLICY_FLAG_EMPTY, uid, r.sdkSandboxClientAppPackage);
5920	                r.isolationHostProc = app;
5921	            } else {
5922	                app = mAm.startProcessLocked(procName, r.appInfo, true, intentFlags,
5923	                        hostingRecord, ZYGOTE_POLICY_FLAG_EMPTY, false, isolated);
5924	            }
5925	            if (app == null) {
5926	                String msg = "Unable to launch app "
5927	                        + r.appInfo.packageName + "/"
5928	                        + r.appInfo.uid + " for service "
5929	                        + r.intent.getIntent() + ": process is bad";
5930	                Slog.w(TAG, msg);
5931	                bringDownServiceLocked(r, enqueueOomAdj);
5932	                return msg;
5933	            }
5934	            mAm.mProcessList.getAppStartInfoTracker().handleProcessServiceStart(startTimeNs, app,
5935	                    r);
5936	            if (isolated) {
5937	                r.isolationHostProc = app;
5938	            }
5939	        }
5940	
5941	        if (r.fgRequired) {
5942	            if (DEBUG_FOREGROUND_SERVICE) {
5943	                Slog.v(TAG, "Allowlisting " + UserHandle.formatUid(r.appInfo.uid)
5944	                        + " for fg-service launch");
5945	            }
5946	            mAm.tempAllowlistUidLocked(r.appInfo.uid,
5947	                    mAm.mConstants.mServiceStartForegroundTimeoutMs, REASON_SERVICE_LAUNCH,
5948	                    "fg-service-launch",
5949	                    TEMPORARY_ALLOW_LIST_TYPE_FOREGROUND_SERVICE_ALLOWED,
5950	                    r.mRecentCallingUid);
5951	        }
5952	
5953	        if (!mPendingServices.contains(r)) {
5954	            mPendingServices.add(r);
5955	        }
5956	
5957	        if (r.delayedStop) {
5958	            // Oh and hey we've already been asked to stop!
5959	            r.delayedStop = false;
5960	            if (r.startRequested) {
5961	                if (DEBUG_DELAYED_STARTS) Slog.v(TAG_SERVICE,
5962	                        "Applying delayed stop (in bring up): " + r);
5963	                stopServiceLocked(r, enqueueOomAdj);
5964	            }
5965	        }
5966	
5967	        return null;
5968	    }
