5990	    private int getServiceBindingOomAdjPolicyForAddLocked(ProcessRecord clientApp,
5991	            ProcessRecord hostApp, ConnectionRecord cr) {
5992	        @ServiceBindingOomAdjPolicy int policy = SERVICE_BIND_OOMADJ_POLICY_LEGACY;
5993	        if (Flags.serviceBindingOomAdjPolicy() && clientApp != null && hostApp != null) {
5994	            if (clientApp == hostApp) {
5995	                policy = DEFAULT_SERVICE_NO_BUMP_BIND_POLICY_FLAG;
5996	            } else if (clientApp.isCached()) {
5997	                policy = DEFAULT_SERVICE_NO_BUMP_BIND_POLICY_FLAG;
5998	                if (clientApp.isFreezable()) {
5999	                    policy |= SERVICE_BIND_OOMADJ_POLICY_FREEZE_CALLER;

6000	                }
6001	            }
6002	            if ((policy & SERVICE_BIND_OOMADJ_POLICY_SKIP_OOM_UPDATE_ON_CONNECT) == 0) {
6003	                // Binding between two different processes.
6004	                // Check if the caller has a better process state, oom adj score,
6005	                // or if the caller has more capabilities.
6006	                if (!mAm.mOomAdjuster.evaluateServiceConnectionAdd(clientApp, hostApp, cr)) {
6007	                    // Running an oom adjuster won't be give the host app a better score, skip it.
6008	                    policy = DEFAULT_SERVICE_NO_BUMP_BIND_POLICY_FLAG;
6009	                }
6010	            }
6011	        }
6012	        return policy;
6013	    }
