6033	    /**
6034	     * Note the name of this method should not be confused with the started services concept.
6035	     * The "start" here means bring up the instance in the client, and this method is called
6036	     * from bindService() as well.
6037	     */
6038	    private void realStartServiceLocked(ServiceRecord r, ProcessRecord app,
6039	            IApplicationThread thread, int pid, UidRecord uidRecord, boolean execInFg,
6040	            boolean enqueueOomAdj, @ServiceBindingOomAdjPolicy int serviceBindingOomAdjPolicy)
6041	            throws RemoteException {
6042	        if (thread == null) {
6043	            throw new RemoteException();
6044	        }
6045	        if (DEBUG_MU)
6046	            Slog.v(TAG_MU, "realStartServiceLocked, ServiceRecord.uid = " + r.appInfo.uid
6047	                    + ", ProcessRecord.uid = " + app.uid);
6048	        r.setProcess(app, thread, pid, uidRecord);
6049	        final long now = SystemClock.uptimeMillis();
6050	        r.restartTime = now;
6051	        mAm.mProcessStateController.setServiceLastActivityTime(r, now);
6052	        final boolean skipOomAdj = (serviceBindingOomAdjPolicy
6053	                & SERVICE_BIND_OOMADJ_POLICY_SKIP_OOM_UPDATE_ON_CREATE) != 0;
6054	        final ProcessServiceRecord psr = app.mServices;
6055	        final boolean newService = mAm.mProcessStateController.startService(psr, r);
6056	        bumpServiceExecutingLocked(r, execInFg, "create",
6057	                OOM_ADJ_REASON_NONE /* use "none" to avoid extra oom adj */,
6058	                skipOomAdj /* skipTimeoutIfPossible */);
6059	        mAm.updateLruProcessLocked(app, false, null);
6060	        updateServiceForegroundLocked(psr, /* oomAdj= */ false);
6061	        // Skip the oom adj update if it's a self-binding, the Service#onCreate() will be running
6062	        // at its current adj score.
6063	        if (!skipOomAdj) {
6064	            // Force an immediate oomAdjUpdate, so the host app could be in the correct
6065	            // process state before doing any service related transactions
6066	            mAm.enqueueOomAdjTargetLocked(app);
6067	            r.updateOomAdjSeq();
6068	            mAm.updateOomAdjPendingTargetsLocked(OOM_ADJ_REASON_START_SERVICE);
6069	        } else {
6070	            // Since we skipped the oom adj update, the Service#onCreate() might be running in
6071	            // the cached state, if the service process drops into the cached state after the call.
6072	            // But there is still a grace period before freezing it, so we should be fine
6073	            // in terms of not getting an ANR.
6074	        }
6075	
6076	        boolean created = false;
6077	        try {
6078	            if (LOG_SERVICE_START_STOP) {
6079	                String nameTerm;
6080	                int lastPeriod = r.shortInstanceName.lastIndexOf('.');
6081	                nameTerm = lastPeriod >= 0 ? r.shortInstanceName.substring(lastPeriod)
6082	                        : r.shortInstanceName;
6083	                EventLogTags.writeAmCreateService(
6084	                        r.userId, System.identityHashCode(r), nameTerm, r.app.uid, pid);
6085	            }
6086	
6087	            final int uid = r.appInfo.uid;
6088	            final String packageName = r.name.getPackageName();
6089	            final String serviceName = r.name.getClassName();
6090	            FrameworkStatsLog.write(FrameworkStatsLog.SERVICE_LAUNCH_REPORTED, uid, packageName,
6091	                    serviceName);
6092	            mAm.mBatteryStatsService.noteServiceStartLaunch(uid, packageName, serviceName);
6093	            mAm.notifyPackageUse(r.serviceInfo.packageName,
6094	                                 PackageManager.NOTIFY_PACKAGE_USE_SERVICE);
6095	            thread.scheduleCreateService(r, r.serviceInfo,
6096	                    null /* compatInfo (unused but need to keep method signature) */,
6097	                    app.mState.getReportedProcState());
6098	            r.postNotification(false);
6099	            created = true;
6100	        } catch (DeadObjectException e) {
6101	            Slog.w(TAG, "Application dead when creating service " + r);
6102	            mAm.appDiedLocked(app, "Died when creating service");
6103	            throw e;
6104	        } finally {
6105	            if (!created) {
6106	                // Keep the executeNesting count accurate.
6107	                final boolean inDestroying = mDestroyingServices.contains(r);
6108	                serviceDoneExecutingLocked(r, inDestroying, inDestroying, false,
6109	                        !Flags.serviceBindingOomAdjPolicy() || r.wasOomAdjUpdated()
6110	                        ? OOM_ADJ_REASON_STOP_SERVICE : OOM_ADJ_REASON_NONE);
6111	
6112	                // Cleanup.
6113	                if (newService) {
6114	                    mAm.mProcessStateController.stopService(psr, r);
6115	                    r.setProcess(null, null, 0, null);
6116	                }
6117	
6118	                // Retry.
6119	                if (!inDestroying) {
6120	                    scheduleServiceRestartLocked(r, false);
6121	                }
6122	            }
6123	        }
6124	
6125	        if (r.allowlistManager) {
6126	            psr.mAllowlistManager = true;
6127	        }
6128	
6129	        requestServiceBindingsLocked(r, execInFg, serviceBindingOomAdjPolicy);
6130	
6131	        updateServiceClientActivitiesLocked(psr, null, true);
6132	
6133	        if (newService && created) {
6134	            psr.addBoundClientUidsOfNewService(r);
6135	        }
6136	
6137	        // If the service is in the started state, and there are no
6138	        // pending arguments, then fake up one so its onStartCommand() will
6139	        // be called.
6140	        if (r.startRequested && r.callStart && r.pendingStarts.size() == 0) {
6141	            r.pendingStarts.add(new ServiceRecord.StartItem(r, false, r.makeNextStartId(),
6142	                    null, null, 0, null, null, ActivityManager.PROCESS_STATE_UNKNOWN));
6143	        }
6144	
6145	        sendServiceArgsLocked(r, execInFg, r.wasOomAdjUpdated());
6146	
6147	        if (r.delayed) {
6148	            if (DEBUG_DELAYED_STARTS) Slog.v(TAG_SERVICE, "REM FR DELAY LIST (new proc): " + r);
6149	            getServiceMapLocked(r.userId).mDelayedStartList.remove(r);
6150	            r.delayed = false;
6151	        }
6152	
6153	        if (r.delayedStop) {
6154	            // Oh and hey we've already been asked to stop!
6155	            r.delayedStop = false;
6156	            if (r.startRequested) {
6157	                if (DEBUG_DELAYED_STARTS) Slog.v(TAG_SERVICE,
6158	                        "Applying delayed stop (from start): " + r);
6159	                stopServiceLocked(r, enqueueOomAdj);
6160	            }
6161	        }
6162	    }
