6261	    private final boolean isServiceNeededLocked(ServiceRecord r, boolean knowConn,
6262	            boolean hasConn) {
6263	        // Are we still explicitly being asked to run?
6264	        if (r.startRequested) {
6265	            return true;
6266	        }
6267	
6268	        // Is someone still bound to us keeping us running?
6269	        if (!knowConn) {
6270	            hasConn = r.hasAutoCreateConnections();
6271	        }
6272	        if (hasConn) {
6273	            return true;
6274	        }
6275	
6276	        return false;
6277	    }
