6297	    private void bringDownServiceLocked(ServiceRecord r, boolean enqueueOomAdj) {
6298	        //Slog.i(TAG, "Bring down service:");
6299	        //r.dump("  ");
6300	
6301	        if (r.isShortFgs()) {
6302	            // FGS can be stopped without the app calling stopService() or stopSelf(),
6303	            // due to force-app-standby, or from Task Manager.
6304	            Slog.w(TAG_SERVICE, "Short FGS brought down without stopping: " + r);
6305	            maybeStopShortFgsTimeoutLocked(r);
6306	        }
6307	
6308	        // Report to all of the connections that the service is no longer
6309	        // available.
6310	        ArrayMap<IBinder, ArrayList<ConnectionRecord>> connections = r.getConnections();
6311	        for (int conni = connections.size() - 1; conni >= 0; conni--) {
6312	            ArrayList<ConnectionRecord> c = connections.valueAt(conni);
6313	            for (int i=0; i<c.size(); i++) {
6314	                ConnectionRecord cr = c.get(i);
6315	                // There is still a connection to the service that is
6316	                // being brought down.  Mark it as dead.
6317	                cr.serviceDead = true;
6318	                cr.stopAssociation();
6319	                final ComponentName clientSideComponentName =
6320	                        cr.aliasComponent != null ? cr.aliasComponent : r.name;
6321	                try {
6322	                    cr.conn.connected(clientSideComponentName, null, true);
6323	                } catch (Exception e) {
6324	                    Slog.w(TAG, "Failure disconnecting service " + r.shortInstanceName
6325	                          + " to connection " + c.get(i).conn.asBinder()
6326	                          + " (in " + c.get(i).binding.client.processName + ")", e);
6327	                }
6328	            }
6329	        }
6330	
6331	        boolean oomAdjusted = Flags.serviceBindingOomAdjPolicy() && r.wasOomAdjUpdated();
6332	
6333	        // Tell the service that it has been unbound.
6334	        if (r.app != null && r.app.isThreadReady()) {
6335	            for (int i = r.bindings.size() - 1; i >= 0; i--) {
6336	                IntentBindRecord ibr = r.bindings.valueAt(i);
6337	                if (DEBUG_SERVICE) Slog.v(TAG_SERVICE, "Bringing down binding " + ibr
6338	                        + ": hasBound=" + ibr.hasBound);
6339	                if (ibr.hasBound) {
6340	                    try {
6341	                        bumpServiceExecutingLocked(r, false, "bring down unbind",
6342	                                oomAdjusted ? OOM_ADJ_REASON_NONE : OOM_ADJ_REASON_UNBIND_SERVICE,
6343	                                oomAdjusted /* skipTimeoutIfPossible */);
6344	                        oomAdjusted |= r.wasOomAdjUpdated();
6345	                        ibr.hasBound = false;
6346	                        ibr.requested = false;
6347	                        r.app.getThread().scheduleUnbindService(r,
6348	                                ibr.intent.getIntent());
6349	                    } catch (Exception e) {
6350	                        Slog.w(TAG, "Exception when unbinding service "
6351	                                + r.shortInstanceName, e);
6352	                        serviceProcessGoneLocked(r, enqueueOomAdj);
6353	                        break;
6354	                    }
6355	                }
6356	            }
6357	        }
6358	
6359	        // Check to see if the service had been started as foreground, but being
6360	        // brought down before actually showing a notification.  That is not allowed.
6361	        if (r.fgRequired) {
6362	            Slog.w(TAG_SERVICE, "Bringing down service while still waiting for start foreground: "
6363	                    + r);
6364	            r.fgRequired = false;
6365	            r.fgWaiting = false;
6366	            synchronized (mAm.mProcessStats.mLock) {
6367	                ServiceState stracker = r.getTracker();
6368	                if (stracker != null) {
6369	                    stracker.setForeground(false, mAm.mProcessStats.getMemFactorLocked(),
6370	                            SystemClock.uptimeMillis());
6371	                }
6372	            }
6373	            mAm.mAppOpsService.finishOperation(AppOpsManager.getToken(mAm.mAppOpsService),
6374	                    AppOpsManager.OP_START_FOREGROUND, r.appInfo.uid, r.packageName, null);
6375	            mServiceFGAnrTimer.cancel(r);
6376	            if (r.app != null) {
6377	                Message msg = mAm.mHandler.obtainMessage(
6378	                        ActivityManagerService.SERVICE_FOREGROUND_CRASH_MSG);
6379	                SomeArgs args = SomeArgs.obtain();
6380	                args.arg1 = r.app;
6381	                args.arg2 = r.toString();
6382	                args.arg3 = r.getComponentName();
6383	
6384	                msg.obj = args;
6385	                mAm.mHandler.sendMessage(msg);
6386	            }
6387	        }
6388	
6389	        if (DEBUG_SERVICE) {
6390	            RuntimeException here = new RuntimeException();
6391	            here.fillInStackTrace();
6392	            Slog.v(TAG_SERVICE, "Bringing down " + r + " " + r.intent, here);
6393	        }
6394	        r.destroyTime = SystemClock.uptimeMillis();
6395	        if (LOG_SERVICE_START_STOP) {
6396	            EventLogTags.writeAmDestroyService(
6397	                    r.userId, System.identityHashCode(r), (r.app != null) ? r.app.getPid() : -1);
6398	        }
